  const req = { id: novoId(), date: hojeISO(), page: contexto || nomePaginaJarvis(), canal: 'jarvis', area: area || null, text: txt || `📎 ${plural(anexos.length, 'print', 'prints')}`, status: 'fila', anexos: anexos.length, resumo: resumo || '', permissao };
