  [['producao', 'capacidade'], ['contabil', 'custos e margens'], ['consignacao', 'giro dos expositores'], ['shopee', 'anúncios e preços'], ['digital', 'e-book']].forEach(([de, rot]) => F.push({ de, para: 'prospeccao', rot, lateral: true }));
