// ============================================================================
// SINCRONIZAÇÃO (Google Sheets via Apps Script — ver sync/Code.gs)
// Como funciona: cada módulo (habits, shifts, ...) tem um carimbo de hora
// "updatedAt" da última vez que foi salvo neste aparelho. Ao sincronizar, o
// app manda tudo com os carimbos; o Code.gs guarda só o que for mais novo do
// que a planilha tem e devolve o estado final; o app adota daqui o que a
// planilha tiver de mais novo. Em empate, a planilha vence.
// URL e token ficam SÓ no localStorage deste aparelho (aba Config).
// ============================================================================
const SYNC_MODULOS = ['habits', 'habitlog', 'orders', 'clients', 'clauderequests', 'familia', 'memorias', 'jarvischat', 'primosplano', 'agentes', 'estoqueprimos', 'filaimpressao', 'recadosagentes', 'metasprimos', 'shopeeaprov', 'shifts', 'places', 'events', 'finances', 'recurring', 'budget', 'tasks', 'tasklists', 'routines', 'notes', 'entregas', 'media', 'playlists', 'trips', 'contacts', 'devnotes', 'servicos', 'pacientes', 'repasses', 'maquinas', 'filamentos', 'produtos', 'ordens', 'vendas', 'study', 'topics', 'materials', 'sessions', 'ritual', 'assets', 'moves', 'goals', 'projects', 'wealth', 'workouts', 'measures', 'hydration', 'meals', 'medical', 'profile'];
const SYNC_INTERVALO_MS = 30000; // sincronização periódica com o app aberto

let syncMeta = JSON.parse(localStorage.getItem('lifeos_sync_meta')) || null;
if (!syncMeta) {
  // Primeira vez com sync neste aparelho: o que já existe ganha carimbo 1
  // ("existe, mas é antigo") e o que não existe ganha 0.
  syncMeta = {};
  localStorage.setItem('lifeos_sync_meta', JSON.stringify(syncMeta));
}
SYNC_MODULOS.forEach(m => { if (syncMeta[m] === undefined) syncMeta[m] = localStorage.getItem('lifeos_' + m) ? 1 : 0; });
let syncConfig = JSON.parse(localStorage.getItem('lifeos_sync_config')) || { url: '', token: '', agenda: false };
let agendaForcar = false; // botão "Enviar agenda agora"
let syncPendente = localStorage.getItem('lifeos_sync_pendente') === '1';
let syncTimer = null;
let syncResumoTexto = ''; // fase 10: a situação da planilha também aparece dentro do Estoque
let syncEmAndamento = false;
let syncEditouDurante = false; // alguma gravação aconteceu enquanto a rede respondia?

/** Grava um módulo no localStorage, carimba a hora e agenda uma sincronização. */
function salvar(modulo, valor) {
  if (typeof protegerEsvaziamento === 'function') protegerEsvaziamento(modulo, valor);
  // Auditoria do Codex (achado 4): conteúdo e carimbo andam juntos. Se faltar espaço no aparelho no meio do caminho, desfaz tudo
  // (senão o conteúdo novo ficava com o carimbo velho e a planilha devolvia a versão antiga) e avisa que NÃO salvou.
  const chave = 'lifeos_' + modulo, antes = localStorage.getItem(chave), carimboAntes = syncMeta[modulo];
  try {
    localStorage.setItem(chave, JSON.stringify(valor));
    syncMeta[modulo] = Math.max(Date.now(), (Number(carimboAntes) || 0) + 1); // ideia do Codex: o carimbo nunca anda para trás
    localStorage.setItem('lifeos_sync_meta', JSON.stringify(syncMeta));
  } catch (e) {
    try { if (antes === null) localStorage.removeItem(chave); else localStorage.setItem(chave, antes); } catch (e2) { }
    if (carimboAntes === undefined) delete syncMeta[modulo]; else syncMeta[modulo] = carimboAntes;
    console.error('salvar:', modulo, e);
    toast('⚠️ Sem espaço no aparelho: a última alteração NÃO foi salva. Apague fotos ou anexos antigos e tente de novo.', 7000);
    setSyncStatus('erro', 'a última alteração NÃO foi salva neste aparelho (sem espaço)');
    return false;
  }
  if (typeof renderAvisos === 'function') setTimeout(renderAvisos, 0);
  syncEditouDurante = true;
  marcarPendente(true);
  agendarSync();
  return true;
}

function marcarPendente(v) {
  syncPendente = v;
  localStorage.setItem('lifeos_sync_pendente', v ? '1' : '0');
  if (v && !syncEmAndamento) setSyncStatus('pendente');
}

/** Espera 2,5 s depois da última alteração antes de sincronizar (junta várias edições numa só). */
function agendarSync() {
  clearTimeout(syncTimer);
  syncTimer = setTimeout(() => sincronizar(), 2500);
}

function syncConfigurado() { return !!(syncConfig.url && syncConfig.token); }

/** fase 10 (pedido do Codex): devolve { estado: ok|erro|offline|naoconfig, mudou } e reaproveita o envio em andamento. */
let syncPromessa = null;
function sincronizar() { if (syncEmAndamento && syncPromessa) return syncPromessa; syncPromessa = sincronizarAgora(); return syncPromessa; }
async function sincronizarAgora() {
  if (!syncConfigurado()) { setSyncStatus('naoconfig'); registrarDiagSync({ ok: false, erro: 'a sincronização não está configurada neste aparelho' }); verificarNovoDia(); return { estado: 'naoconfig' }; }
  if (syncEmAndamento) return { estado: 'andamento' };
  if (!navigator.onLine) { setSyncStatus('offline'); verificarNovoDia(); return { estado: 'offline' }; }
  let resultado = { estado: 'ok', mudou: [] };

  syncEmAndamento = true; syncEditouDurante = false; setSyncStatus('andamento');
  const controle = typeof AbortController !== 'undefined' ? new AbortController() : null, limite = setTimeout(() => controle && controle.abort(), 25000); // fase 9: não fica preso
  try {
    // fase 9 (04/10/2026): a planilha aceita até 50 mil letras por célula — e UM módulo grande derrubava o envio de TODOS daquele
    // aparelho. Módulo grande vai em pedaços ("modulo#1", "modulo#2"…, mesmo carimbo); quem recebe junta (valorRemoto).
    const dados = {}, PEDACO = 22000;
    SYNC_MODULOS.forEach(m => {
      const bruto = localStorage.getItem('lifeos_' + m); if (bruto === null) return;
      const quando = syncMeta[m] || 0;
      if (bruto.length <= PEDACO) { dados[m] = { updatedAt: quando, valor: JSON.parse(bruto) }; return; }
      const n = Math.ceil(bruto.length / PEDACO); dados[m] = { updatedAt: quando, valor: { __partes: n } };
      for (let i = 0; i < n; i++) dados[`${m}#${i + 1}`] = { updatedAt: quando, valor: bruto.slice(i * PEDACO, (i + 1) * PEDACO) };
    });

    // Google Calendar: só pede o espelhamento quando plantões/compromissos mudaram desde o último envio
    const agendaStamp = Number(localStorage.getItem('lifeos_agenda_stamp')) || 0;
    const precisaAgenda = !!syncConfig.agenda && (agendaForcar || (syncMeta.shifts || 0) > agendaStamp || (syncMeta.events || 0) > agendaStamp);
    const agendaEnviada = Math.max((dados.shifts || {}).updatedAt || 0, (dados.events || {}).updatedAt || 0); // o que FOI enviado (auditoria do Codex, achado 7)
    agendaForcar = false;

    // Content-Type text/plain de propósito: evita o "preflight" CORS que o Apps Script não responde.
    const resp = await fetch(syncConfig.url, {
      method: 'POST', ...(controle ? { signal: controle.signal } : {}),
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({ token: syncConfig.token, acao: 'push', dados, agenda: precisaAgenda })
    });
    if (!resp.ok) throw new Error('a planilha respondeu HTTP ' + resp.status);
    const r = await resp.json();
    if (!r.ok) throw new Error(r.erro || 'resposta inválida do servidor');
    if (!r.dados || typeof r.dados !== 'object') throw new Error('a planilha não devolveu os dados');

    const mudou = aplicarRemoto(r.dados); // lista dos módulos que chegaram mais novos
    // fase 9 (ideia do Codex): só diz "sincronizado" se a planilha guardou TUDO o que este aparelho mandou
    const naoGuardou = Object.keys(dados).filter(k => !r.dados[k] || (Number(r.dados[k].updatedAt) || 0) < (dados[k].updatedAt || 0)).filter(k => !k.includes('#'));
    registrarDiagSync({ ok: !naoGuardou.length, erro: naoGuardou.length ? 'a planilha não guardou: ' + naoGuardou.join(', ') : '', aqui: Object.keys(dados).filter(k => !k.includes('#')).length, planilha: Object.keys(r.dados).filter(k => !k.includes('#')).length, grandes: Object.keys(dados).filter(k => k.endsWith('#1')).map(k => k.slice(0, -2)) });
    if (naoGuardou.length) { if (mudou.length) redesenharTudo(mudou); throw new Error('a planilha não guardou: ' + naoGuardou.join(', ')); }
    if (precisaAgenda) {
      if (r.agenda && r.agenda.ok) {
        localStorage.setItem('lifeos_agenda_stamp', String(agendaEnviada)); // edição feita durante o envio continua pendente para a agenda
        const a = r.agenda; setAgendaStatus('ok', `${a.total} na agenda · +${a.criados} criado${a.criados === 1 ? '' : 's'}, ${a.atualizados} atualizado${a.atualizados === 1 ? '' : 's'}, ${a.removidos} removido${a.removidos === 1 ? '' : 's'}`);
      } else if (r.agenda) setAgendaStatus('erro', r.agenda.erro || 'falha no Calendar');
      else setAgendaStatus('erro', 'o Code.gs implantado ainda é a versão 1 (sem agenda). Cole a v2 e crie uma nova versão da implantação.');
    }
    // se algo foi editado enquanto a rede respondia, continua pendente
    const editouDurante = syncEditouDurante;
    marcarPendente(editouDurante);
    localStorage.setItem('lifeos_sync_ultima', String(Date.now()));
    setSyncStatus(editouDurante ? 'pendente' : 'ok');
    if (mudou.length) redesenharTudo(mudou);
    if (editouDurante) agendarSync();
    resultado = { estado: 'ok', mudou };
  } catch (err) {
    console.error('Sync:', err);
    const msg = err && err.name === 'AbortError' ? 'a planilha demorou demais para responder (vou tentar de novo)' : String(err.message || err);
    if (!/não guardou/.test(msg)) registrarDiagSync({ ok: false, erro: msg });
    marcarPendente(true);
    setSyncStatus(navigator.onLine ? 'erro' : 'offline', msg);
    resultado = { estado: navigator.onLine ? 'erro' : 'offline', erro: msg };
  } finally {
    clearTimeout(limite); syncEmAndamento = false;
    // Só depois de saber o estado mais novo é que fechamos o dia anterior
    // (evita que um aparelho zere hábitos que o outro já marcou hoje).
    verificarNovoDia();
  }
  return resultado;
}

/** Adota o que veio da planilha se for mais novo (ou igual e diferente — empate: planilha vence). */
function aplicarRemoto(remoto) {
  const mudou = [];
  SYNC_MODULOS.forEach(m => {
    const r = valorRemoto(remoto, m);
    if (!r || !Number.isFinite(Number(r.updatedAt))) return;
    const local = syncMeta[m] || 0;
    if (r.updatedAt < local) return;
    if (r.updatedAt === local && r.texto === localStorage.getItem('lifeos_' + m)) return;
    try { localStorage.setItem('lifeos_' + m, r.texto); } catch (e) { console.error('sync: sem espaço para', m); return; }
    syncMeta[m] = r.updatedAt; // sem carimbar hora nova: isso não é edição local
    mudou.push(m);
  });
  try { localStorage.setItem('lifeos_sync_meta', JSON.stringify(syncMeta)); } catch (e) { }
  return mudou;
}
/** O módulo como veio da planilha — juntando os pedaços de um módulo grande (fase 9). null = não veio inteiro (fica o daqui). */
function valorRemoto(remoto, m) {
  const r = remoto[m]; if (!r || r.valor === null || r.valor === undefined) return null;
  if (typeof r.valor === 'object' && !Array.isArray(r.valor) && r.valor.__partes) {
    let txt = '';
    for (let i = 1; i <= r.valor.__partes; i++) { const p = remoto[`${m}#${i}`]; if (!p || p.updatedAt !== r.updatedAt || typeof p.valor !== 'string') return null; txt += p.valor; }
    try { JSON.parse(txt); } catch (e) { return null; }
    return { updatedAt: r.updatedAt, texto: txt };
  }
  return { updatedAt: r.updatedAt, texto: JSON.stringify(r.valor) };
}
/** Saúde da sincronização deste aparelho (aparece em Ajustes, no aviso da página inicial e no cofre para o Claude ver). */
function lerDiagSync() { try { return JSON.parse(localStorage.getItem('lifeos_sync_diag')) || {}; } catch (e) { return {}; } }
function registrarDiagSync(d) {
  const antes = lerDiagSync(), agora = { ...antes, ...d, quando: Date.now(), ...(d.ok ? { ultimoOk: Date.now(), erro: '' } : {}) };
  try { localStorage.setItem('lifeos_sync_diag', JSON.stringify(agora)); } catch (e) { }
  publicarSaudeAparelho(agora, antes.ok !== agora.ok);
}
function idPlanilha() { const m = String(syncConfig.url || '').match(/\/macros\/s\/([^/]+)\//); return m ? '…' + m[1].slice(-6) : 'nenhuma'; }
function nomeAparelho() {
  const u = navigator.userAgent, so = /iPhone/.test(u) ? 'iPhone' : /iPad/.test(u) ? 'iPad' : /Android/.test(u) ? 'Android' : /Windows/.test(u) ? 'Windows' : /Mac OS X/.test(u) ? 'Mac' : 'Outro';
  const nav = /Edg\//.test(u) ? 'Edge' : /CriOS|Chrome\//.test(u) ? 'Chrome' : /Firefox|FxiOS/.test(u) ? 'Firefox' : /Safari/.test(u) ? 'Safari' : '';
  return so + (nav ? ' · ' + nav : '') + (appInstalado() ? ' (app)' : '');
}
function idAparelho() { let id = localStorage.getItem('lifeos_aparelho_id'); if (!id) { id = 'ap' + novoId(); try { localStorage.setItem('lifeos_aparelho_id', id); } catch (e) { } } return id; }
/** No cofre (dados/aparelhos.json): planilha, última sincronização e erro de cada aparelho — no máximo 1×/hora ou quando muda ok↔erro. */
async function publicarSaudeAparelho(d, mudouEstado) {
  if (!claudeConfigurado()) return;
  const ult = Number(localStorage.getItem('lifeos_saude_pub')) || 0; if (!mudouEstado && Date.now() - ult < 60 * 60000) return;
  try { localStorage.setItem('lifeos_saude_pub', String(Date.now())); } catch (e) { }
  try { await gravarCofreJson('dados/aparelhos.json', x => { x = x && x.aparelhos ? x : { tipo: 'jarvis-aparelhos', aparelhos: {} }; x.aparelhos[idAparelho()] = { nome: nomeAparelho(), planilha: idPlanilha(), sincroniza: syncConfigurado(), ok: !!d.ok, erro: String(d.erro || '').slice(0, 200), ultimoOk: d.ultimoOk ? new Date(d.ultimoOk).toISOString() : null, quando: new Date().toISOString(), modulosAqui: d.aqui || 0, modulosPlanilha: d.planilha || 0, central: (primosCentral && primosCentral.geradoEm) || null, bambu: (impressoesBambu && impressoesBambu.lidoEm) || null, estoqueRegistros: estoquePrimos.length, grandes: d.grandes || [], versao: (typeof CACHE_VERSAO !== 'undefined' ? CACHE_VERSAO : '') }; return x; }, `Saúde da sincronização: ${nomeAparelho()}`); } catch (e) { }
}

/** fase 10 (ideia do Codex): redesenha um painel aberto SEM apagar o que você está digitando. Guarda só o que VOCÊ mudou nos campos
 *  (valor diferente do que veio desenhado), o foco, a seleção do texto, os blocos abertos (<details>) e a rolagem; redesenha e devolve.
 *  Usada quando a planilha (outro aparelho) ou o cofre trazem dados novos com a Central, a Primos ou a página de um agente aberta.
 *  Depois de um envio de formulário NÃO use (o formulário tem mesmo que limpar): chame o render direto. */
function preservarTela(raiz, render) {
  if (!raiz || raiz.hidden) return;
  const chave = el => el.id ? '#' + el.id : el.closest('.estc-lin') ? 'contagem:' + el.closest('.estc-lin').dataset.k : el.name ? 'nome:' + el.name : '';
  const mudou = el => el.tagName === 'SELECT' ? [...el.options].some(o => o.selected !== o.defaultSelected) : /^(checkbox|radio)$/.test(el.type) ? el.checked !== el.defaultChecked : el.value !== el.defaultValue;
  const campos = new Map(), foco = document.activeElement, kFoco = foco && raiz.contains(foco) ? chave(foco) : '';
  let sel = null; try { if (kFoco && typeof foco.selectionStart === 'number') sel = [foco.selectionStart, foco.selectionEnd]; } catch (e) { }
  raiz.querySelectorAll('input, textarea, select').forEach(el => { const k = chave(el); if (k && !/^(file|hidden|submit|button)$/.test(el.type) && mudou(el)) campos.set(k, [el.value, el.checked, el.tagName === 'SELECT' && el.selectedOptions[0] ? el.selectedOptions[0].textContent : null]); });
  const detalhes = new Map([...raiz.querySelectorAll('details')].map(d => [(d.querySelector('summary') || d).textContent.trim().slice(0, 80), d.open]));
  const rolagem = [...raiz.querySelectorAll('[id]')].filter(el => el.scrollTop || el.scrollLeft).map(el => [el.id, el.scrollTop, el.scrollLeft]), y0 = raiz.scrollTop;
  render();
  raiz.querySelectorAll('input, textarea, select').forEach(el => { const k = chave(el), v = campos.get(k); if (!v) return; if (/^(checkbox|radio)$/.test(el.type)) el.checked = v[1]; else if (v[2] !== null && el.tagName === 'SELECT') { const o = [...el.options].find(x => x.textContent === v[2]); if (o) el.value = o.value; } else el.value = v[0]; });
  raiz.querySelectorAll('details').forEach(d => { const k = (d.querySelector('summary') || d).textContent.trim().slice(0, 80); if (detalhes.has(k)) d.open = detalhes.get(k); });
  if (y0) raiz.scrollTop = y0; rolagem.forEach(([id, t, l]) => { const el = document.getElementById(id); if (el && raiz.contains(el)) { el.scrollTop = t; el.scrollLeft = l; } });
  if (kFoco) { const el = [...raiz.querySelectorAll('input, textarea, select')].find(x => chave(x) === kFoco); if (el) { try { el.focus({ preventScroll: true }); if (sel && typeof el.setSelectionRange === 'function') el.setSelectionRange(sel[0], sel[1]); } catch (e) { } } }
}
/** fase 10 (achado 5 do Codex): a página de um agente aberta (Estoque, Produção...) também se atualiza quando a planilha traz dados dela.
 *  Só as páginas que mostram módulos sincronizados, e só se um deles mudou (sem mudou = tudo: importação de backup). */
function paginaAgenteMostra(mudou) {
  const mods = { estoque: ['estoqueprimos', 'filaimpressao'], producao: ['filaimpressao', 'estoqueprimos', 'orders'], contabil: ['orders', 'finances', 'estoqueprimos', 'metasprimos'], vendas: ['orders', 'clients', 'metasprimos'], consignacao: ['orders'], shopee: ['shopeeaprov'] }[cc.pagina];
  return !!mods && (!mudou || mudou.some(m => mods.includes(m)));
}
/** Redesenha (preservando o que está sendo digitado) as telas abertas que mostram dados sincronizados. Sem argumentos: Central + Primos. */
function atualizarTelasSincronizadas(...quais) {
  const telas = { central: ['jv-central', renderCentral], primos: ['jv-primos', renderPrimosPagina], agente: ['ag-pag', renderPaginaAgente] };
  (quais.length ? quais : ['central', 'primos']).forEach(q => { const t = telas[q]; if (t) preservarTela($j(t[0]), t[1]); });
}

